import re,pathlib
R=pathlib.Path('.')
debt=(R/'docs/dev/debt/libSceLibcInternal.md').read_text()
inv=re.findall(r"^- \[([^\]]+)\]\(\.\./\.\./\.\./core/libs/prx/libSceLibcInternal/(InventoryExports\d*\.cpp)\) \(libSceLibcInternal, NID `([^`]+)`\) - listed", debt, re.M)
libc={str(p):p.read_text(errors='ignore') for p in (R/'core/libs/prx/libc').rglob('*.cpp') if 'tests' not in p.parts}
allc="\n".join(libc.values())
lci="\n".join(p.read_text(errors='ignore') for p in (R/'core/libs/prx/libSceLibcInternal').rglob('*.cpp') if 'tests' not in p.parts)
for name,f,nid in inv:
    tags=[]
    for nm in {name, name.lstrip('_')}:
        if re.search(r"\bAPS5_VABI\s+"+re.escape(nm)+r"(_nid_postfix|_nid_disambig\d+)?\s*\(",allc): tags.append('libcDEF:'+nm)
        elif re.search(r"\b"+re.escape(nm)+r"\b",allc): tags.append('libcMENTION:'+nm)
        if re.search(r"\bAPS5_VABI\s+\w*"+re.escape(nm)+r"\w*_nid_postfix\s*\(",lci): tags.append('lciDEF')
    print(nid, name, f, ' '.join(tags))
EOF
